import * as net from 'net';
import * as crypto from 'crypto';

interface TenantConfig {
  tenantId: string;
  devicePrefix: string;
  mqttBroker: string;
  allowedTopics: string[];
}

interface DeviceSession {
  socket: net.Socket;
  tenant: TenantConfig;
  deviceId: string;
  authenticated: boolean;
  nonce: string;
}

const tenantRegistry: Map<string, TenantConfig> = new Map();
const activeSessions: Map<string, DeviceSession> = new Map();

// Firmware master key must be provided via environment; never hard-code secrets.
const FIRMWARE_MASTER_KEY = process.env.FIRMWARE_MASTER_KEY;
if (!FIRMWARE_MASTER_KEY) {
  throw new Error('FIRMWARE_MASTER_KEY environment variable is not set');
}

function generateNonce(): string {
  return crypto.randomBytes(16).toString('hex');
}

function sanitizeHeaderValue(value: string): string {
  // Remove null bytes and all control characters including CR/LF
  return value.replace(/[\x00-\x1f\x7f]/g, '');
}

function encodeTenantHeader(tenant: TenantConfig, deviceId: string): string {
  const sanitizedPrefix = sanitizeHeaderValue(tenant.devicePrefix);
  const sanitizedId = sanitizeHeaderValue(deviceId);
  return `X-Tenant-Id: ${tenant.tenantId}\r\nX-Device-Id: ${sanitizedPrefix}-${sanitizedId}`;
}

function buildMqttConnectFrame(session: DeviceSession, topic: string): Buffer {
  const tenantHeader = encodeTenantHeader(session.tenant, session.deviceId);
  const sanitizedTopic = sanitizeHeaderValue(topic);
  const frame = `CONNECT\r\n${tenantHeader}\r\nX-Auth-Nonce: ${session.nonce}\r\nX-Topic: ${sanitizedTopic}\r\n\r\n`;
  return Buffer.from(frame, 'utf-8');
}

function validateTopicAccess(session: DeviceSession, topic: string): boolean {
  const normalizedTopic = topic.trim().toLowerCase();
  return session.tenant.allowedTopics.some(
    allowed => normalizedTopic.startsWith(allowed.toLowerCase())
  );
}

function parseRegistrationPayload(data: Buffer): { tenantId: string; deviceId: string; secret: string } | null {
  try {
    const payload = JSON.parse(data.toString('utf-8'));
    if (typeof payload.tenantId !== 'string' || typeof payload.deviceId !== 'string' || typeof payload.secret !== 'string') {
      return null;
    }
    return { tenantId: payload.tenantId, deviceId: payload.deviceId, secret: payload.secret };
  } catch {
    return null;
  }
}

function authenticateDevice(tenantId: string, deviceId: string, secret: string): boolean {
  const expectedHash = crypto.createHmac('sha256', FIRMWARE_MASTER_KEY as string)
    .update(`${tenantId}:${deviceId}`)
    .digest('hex');
  return crypto.timingSafeEqual(
    Buffer.from(expectedHash, 'hex'),
    Buffer.from(secret.padEnd(64, '0').slice(0, 64), 'hex')
  );
}

function handlePublishCommand(session: DeviceSession, data: Buffer): Buffer {
  const payload = data.toString('utf-8');
  const lines = payload.split('\n');

  if (lines.length < 2) {
    return Buffer.from('ERROR: malformed publish\r\n');
  }

  const topic = lines[0].trim();
  const message = lines.slice(1).join('\n');

  if (!validateTopicAccess(session, topic)) {
    return Buffer.from('ERROR: topic access denied\r\n');
  }

  const connectFrame = buildMqttConnectFrame(session, topic);
  const sanitizedTopic = sanitizeHeaderValue(topic);
  const publishFrame = Buffer.from(`PUBLISH\r\nX-Topic: ${sanitizedTopic}\r\nContent-Length: ${message.length}\r\n\r\n${message}`);

  return Buffer.concat([connectFrame, publishFrame]);
}

function handleConnection(socket: net.Socket): void {
  let session: DeviceSession | null = null;
  let state: 'AWAITING_REG' | 'AUTHENTICATED' = 'AWAITING_REG';

  socket.on('data', (data: Buffer) => {
    if (state === 'AWAITING_REG') {
      const reg = parseRegistrationPayload(data);
      if (!reg) {
        socket.write('ERROR: invalid registration\r\n');
        socket.end();
        return;
      }

      const tenant = tenantRegistry.get(reg.tenantId);
      if (!tenant) {
        socket.write('ERROR: unknown tenant\r\n');
        socket.end();
        return;
      }

      if (!authenticateDevice(reg.tenantId, reg.deviceId, reg.secret)) {
        socket.write('ERROR: authentication failed\r\n');
        socket.end();
        return;
      }

      session = {
        socket,
        tenant,
        deviceId: reg.deviceId,
        authenticated: true,
        nonce: generateNonce()
      };
      activeSessions.set(`${reg.tenantId}:${reg.deviceId}`, session);
      state = 'AUTHENTICATED';
      socket.write(`OK: session established, nonce=${session.nonce}\r\n`);
    } else if (state === 'AUTHENTICATED' && session) {
      const response = handlePublishCommand(session, data);
      socket.write(response);
    }
  });

  socket.on('close', () => {
    if (session) {
      activeSessions.delete(`${session.tenant.tenantId}:${session.deviceId}`);
    }
  });
}

function initializeTenants(): void {
  tenantRegistry.set('acme-corp', {
    tenantId: 'acme-corp',
    devicePrefix: 'acme',
    mqttBroker: 'mqtt://broker.acme.internal',
    allowedTopics: ['sensors/', 'telemetry/']
  });
  tenantRegistry.set('globex-inc', {
    tenantId: 'globex-inc',
    devicePrefix: 'glbx',
    mqttBroker: 'mqtt://broker.globex.internal',
    allowedTopics: ['devices/', 'alerts/']
  });
}

const server = net.createServer(handleConnection);
initializeTenants();
server.listen(8883, '0.0.0.0', () => {
  console.log('IoT Gateway listening on port 8883');
});

export { handlePublishCommand, buildMqttConnectFrame, encodeTenantHeader, sanitizeHeaderValue, validateTopicAccess };
